package com.kovian.finance.liability.domain; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="financial_liabilities") public class FinancialLiability { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(name="owner_id",nullable=false) UUID ownerId; @Column(nullable=false) String name; @Column(name="liability_type",nullable=false) String liabilityType; @Column(nullable=false,precision=19,scale=4) BigDecimal amount; @Column(nullable=false) boolean active=true; @Column(name="updated_at",nullable=false) OffsetDateTime updatedAt=OffsetDateTime.now(); protected FinancialLiability(){} public FinancialLiability(UUID o,String n,String t,BigDecimal a){if(o==null||n==null||n.isBlank()||a==null||a.signum()<0)throw new IllegalArgumentException("Invalid liability");ownerId=o;name=n.trim();liabilityType=t;amount=a;} public UUID getOwnerId(){return ownerId;} public BigDecimal getAmount(){return amount;} public void updateAmount(BigDecimal a){if(a==null||a.signum()<0)throw new IllegalArgumentException("Invalid amount");amount=a;updatedAt=OffsetDateTime.now();}}